1	/**
2	 * manual-witness-hold-probe.mjs — bounded manual-focused route probe (commission step 3).
3	 *
4	 * Runs ONLY after manual-input-gate-probe proved, on hardware, that a real key
5	 * down reaches the shipped gate and moves a grounded body (capture
6	 * verifier/captures/manual-focused/input-gate-1). Same lane: no movie=1, no
7	 * autopilot, no teleport, no route grant, no pose/milestone writes. Every step
8	 * is an ordinary held key, and every arrival is asserted by measured distance
9	 * before the next act is attempted.
10	 *
11	 * Gates reused from the input-gate probe (same source reasoning):
12	 *   pointer lock via a REAL canvas click (CameraControls.tsx:100-114) is what
13	 *   enables `active` in EfficientPlayer.tsx:1565. Without it keys are ignored.
14	 */
15	import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from 'node:fs';
16	import { resolve, join } from 'node:path';
17	import { createHash } from 'node:crypto';
18	import process from 'node:process';
19	import { ART, CAPTURES, REPO_ROOT } from '../lib/cgContract.mjs';
20	import { createOwnedSessionGuard, failureRecord } from '../lib/ownedSession.mjs';
21	import { assertFreshOutputDir, writeSourceSnapshot, snapshotRef } from '../lib/sourceSnapshot.mjs';
22	import { openParavoxia, waitReady, readState } from '../../../../../../main/tools/lib/evidence.mjs';
23	// The pure guards are RE-DECLARED here on purpose: manual-input-gate-probe.mjs
24	// is an executable capture script, so importing it would launch a second
25	// browser. These are byte-identical copies of its already self-tested helpers.
26	const dist3 = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
27	const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
28	export function splitByUp(from, to, up) {
29	  const m0 = Math.hypot(up[0], up[1], up[2]);
30	  const u = m0 < 1e-9 ? [0, 1, 0] : [up[0] / m0, up[1] / m0, up[2] / m0];
31	  const d = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
32	  const v = dot3(d, u);
33	  const h = [d[0] - v * u[0], d[1] - v * u[1], d[2] - v * u[2]];
34	  const hMag = Math.hypot(h[0], h[1], h[2]);
35	  return { vertical: v, horizontal: hMag, hUnit: hMag < 1e-9 ? null : [h[0] / hMag, h[1] / hMag, h[2] / hMag] };
36	}
37	export function bodyUsable(p) {
38	  if (!Array.isArray(p) || p.length !== 3) return { ok: false, why: 'not-a-3-vector' };
39	  if (!p.every((n) => Number.isFinite(n))) return { ok: false, why: 'non-finite' };
40	  if (Math.hypot(p[0], p[1], p[2]) < 1e-6) return { ok: false, why: 'uninitialised-origin-000' };
41	  return { ok: true, why: null };
42	}
43	export function settled(samples, { n = 8, eps = 0.02 } = {}) {
44	  if (samples.length < n) return { ok: false, why: `only ${samples.length} samples`, spread: null };
45	  const tail = samples.slice(-n);
46	  let spread = 0;
47	  for (let i = 0; i < tail.length; i++) for (let j = i + 1; j < tail.length; j++) spread = Math.max(spread, dist3(tail[i], tail[j]));
48	  return { ok: spread <= eps, why: spread <= eps ? null : `spread ${spread.toFixed(4)} > ${eps}`, spread };
