341	    // VERB at the authored witness point (CG_POSES.W, documented in
342	    // commonGroundState.ts as "W-7744's inspection pose, and the off-route
343	    // intermediate witness point"). This is ordinary movement plus the shipped
344	    // prompt; it is not a body-clearance relabel and grants nothing.
345	    const objNow = (await readState(page))?.objectiveId ?? null;
346	    if (objNow === 'ch13:survey:witness' && !witnessTried) {
347	      witnessTried = true;
348	      const wpt = [-34, 51.05, 10];
349	      const legW2 = await walkTo('to-witness-point', wpt, { arrive: 1.0, budgetMs: 60000 });
350	      const atWit = await snapState('at-witness-point');
351	      report.witnessLeg = { reached: legW2.reached, finalDistance: legW2.finalDistance, prompts: atWit.prompts, holdReason: atWit.holdReason };
352	      gate('reached-the-authored-witness-point', legW2.reached === true, report.witnessLeg);
353	      if ((atWit.prompts ?? []).some((p) => /\bF\b/.test(p ?? ''))) { await pressF('the authored witness prompt at the witness point'); await snapState('after-witness-F'); }
354	      else say('no F prompt at the witness point; not pressing F');
355	      continue;
356	    }
357	    if (rec.prompts.some((p) => /\bF\b/.test(p ?? '')) && (w?.witnessOffered === true)) { await pressF('the shipped witness prompt was offered during W\'s test'); }
358	    await sleep(2000);
359	  }
360	  report.witnessWatch = { elapsedMs: Date.now() - tw, samples: watch.length, routeTested: tested, workerTravelledUnits: workerMoved,
361	    lastHoldReason: watch.length ? watch[watch.length - 1].holdReason : null, last: watch.length ? watch[watch.length - 1] : null, series: watch };
362	  gate('W-actually-tested-the-route', tested, { routeTested: tested, lastHoldReason: report.witnessWatch.lastHoldReason,
363	    workerTravelledUnits: workerMoved, lastSurvey: report.witnessWatch.last?.survey ?? null });
364	  await snapState('witness-watch-end');
365	
366	  report.verdict = report.deviation && report.deviation.returned && report.surveyFinal.samples > 0
367	    && drawLegs.every((l) => l.reached) ? 'CORNER-RECOVERY-OBSERVED'
368	    : report.deviation ? 'PARTIAL-DRAW' : 'SURVEY-STARTED-NO-CORNER-PROOF';
369	  report.finalCg = await cgSnap(page); report.finalState = await readState(page);
370	} catch (err) {
371	  if (!err.gateStop) { report.verdict = 'ERROR'; report.error = String(err).slice(0, 400); }
372	  report.failure = failureRecord({ probe: 'manual-witness-hold-probe.mjs', error: err, phase: report.stoppedAt ?? 'capture' });
373	  say(`STOP: ${String(err).slice(0, 300)}`);
374	} finally {
375	  await guard.stopOnce('probe-finally');
376	  report.cleanup = guard.cleanupReceipt({ probe: 'manual-witness-hold-probe.mjs' });
377	  report.finishedAt = new Date().toISOString(); report.elapsedMs = Date.now() - t0;
378	  const body = JSON.stringify(report, null, 1);
379	  writeFileSync(join(outDir, 'summary.json'), body);
380	  writeFileSync(join(outDir, 'summary.sha256'), `${sha(body)}  summary.json\n`);
381	  say(`verdict=${report.verdict} out=${outDir}`);
382	}
383	process.exit(report.verdict === 'CORNER-RECOVERY-OBSERVED' ? 0 : 2);
384

